-- Sprint 1c (D-041): the Systems, Journey and About pages' own hero images (one landscape image each, shown behind the top of the page). Systems — a dark circuit board with orange traces; Journey — an empty road to a dawn horizon; About — an engineer's desk at night.
-- Generated by scripts/build-hero-photos.mjs --replace; the encoded image(s) are in design/hero/. The slot's current
-- photo is superseded (BR-1.17: kept, never altered or deleted) and the new one becomes current — the owner can replace
-- it in Admin → Photos at any time. Additive only.


UPDATE "ProfilePhoto" SET "supersededAt" = now() WHERE "purpose" = 'hero-systems' AND "supersededAt" IS NULL AND "sha256" <> 'b1f1b7e709f6a11c201da8148534122b4b79caf6bcca40cba841059e8a6dda01';

INSERT INTO "ProfilePhoto" ("id", "purpose", "altText", "mimeType", "width", "height", "byteSize", "sha256", "fileData")
SELECT gen_random_uuid()::text, 'hero-systems', 'A decorative image behind the top of the page', 'image/webp', 1280, 853, 105546, 'b1f1b7e709f6a11c201da8148534122b4b79caf6bcca40cba841059e8a6dda01', decode('', 'base64')
WHERE NOT EXISTS (SELECT 1 FROM "ProfilePhoto" WHERE "purpose" = 'hero-systems' AND "supersededAt" IS NULL);

UPDATE "ProfilePhoto" SET "supersededAt" = now() WHERE "purpose" = 'hero-journey' AND "supersededAt" IS NULL AND "sha256" <> '5f758058247da44f171efb6a49823b97e98a2d3362a1ad7919806991bef47f1b';

INSERT INTO "ProfilePhoto" ("id", "purpose", "altText", "mimeType", "width", "height", "byteSize", "sha256", "fileData")
SELECT gen_random_uuid()::text, 'hero-journey', 'A decorative image behind the top of the page', 'image/webp', 1280, 853, 35626, '5f758058247da44f171efb6a49823b97e98a2d3362a1ad7919806991bef47f1b', decode('', 'base64')
WHERE NOT EXISTS (SELECT 1 FROM "ProfilePhoto" WHERE "purpose" = 'hero-journey' AND "supersededAt" IS NULL);

UPDATE "ProfilePhoto" SET "supersededAt" = now() WHERE "purpose" = 'hero-about' AND "supersededAt" IS NULL AND "sha256" <> '297e8ea8233923f9b28a266409b7af88d9f998962ae5c94020f8ecbc2c1887af';

INSERT INTO "ProfilePhoto" ("id", "purpose", "altText", "mimeType", "width", "height", "byteSize", "sha256", "fileData")
SELECT gen_random_uuid()::text, 'hero-about', 'A decorative image behind the top of the page', 'image/webp', 1280, 853, 37912, '297e8ea8233923f9b28a266409b7af88d9f998962ae5c94020f8ecbc2c1887af', decode('', 'base64')
WHERE NOT EXISTS (SELECT 1 FROM "ProfilePhoto" WHERE "purpose" = 'hero-about' AND "supersededAt" IS NULL);
